import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const x=JSON.parse('{"title":"选项速查表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/reference.md","filePath":"appendix/reference.md","lastUpdated":null}'),o={name:"appendix/reference.md"};function l(h,t,n,c,i,s){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="选项速查表" tabindex="-1">选项速查表 <a class="header-anchor" href="#选项速查表" aria-label="Permalink to &quot;选项速查表&quot;">​</a></h1><p>本文汇总平台中各类下拉选项与术语对照，供查阅。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td>`Alt + ``</td><td>首页</td></tr><tr><td><code>Alt + 1</code></td><td>网关管理</td></tr><tr><td><code>Alt + 2</code></td><td>模组管理</td></tr><tr><td><code>Alt + 8</code></td><td>活跃行情报价</td></tr><tr><td><code>Alt + 9</code></td><td>多图同列</td></tr><tr><td><code>Alt + 0</code></td><td>平台日志</td></tr><tr><td><code>Alt + Q</code></td><td>回放：预加载 / 播放 / 暂停（按状态智能切换）</td></tr><tr><td><code>Alt + W</code></td><td>回放：逐K回放</td></tr><tr><td><code>Alt + S</code></td><td>回放：状态重置</td></tr></tbody></table><h2 id="网关渠道-channeltype" tabindex="-1">网关渠道（ChannelType） <a class="header-anchor" href="#网关渠道-channeltype" aria-label="Permalink to &quot;网关渠道（ChannelType）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th style="text-align:center;">行情</th><th style="text-align:center;">交易</th><th>说明</th></tr></thead><tbody><tr><td>PLAYBACK</td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td>历史回放（内置）</td></tr><tr><td>SIM</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>模拟撮合（内置，零配置）</td></tr><tr><td>CTP</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>期货实盘（外部 jar）</td></tr><tr><td>CTP_SIM</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>CTP 仿真（仅超级用户可见）</td></tr><tr><td>TIGER</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>老虎证券（外部 jar）</td></tr><tr><td>OKX</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>OKX（外部 jar）</td></tr><tr><td>BIAN</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td>币安（外部 jar）</td></tr></tbody></table><h2 id="回放选项" tabindex="-1">回放选项 <a class="header-anchor" href="#回放选项" aria-label="Permalink to &quot;回放选项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>取值</th><th>说明</th></tr></thead><tbody><tr><td>回放精度</td><td>低 / 中 / 高</td><td>每分钟 4 / 30 / 120 个 TICK</td></tr><tr><td>回放速度</td><td>滑块无级调节</td><td>提示&quot;每TICK间隔 n 毫秒&quot;，正常 ↔ 极速</td></tr><tr><td>逐K步长</td><td>1m / 3m / 5m / 10m / 15m / 30m / 1h / 2h / 4h</td><td>逐K回放每次推进的周期</td></tr><tr><td>回放状态</td><td>INITIAL → PRELOADING → PRELOADED → PLAYING → FINISHED</td><td>初始 → 预加载中 → 预加载完成 → 回放中 → 已结束</td></tr></tbody></table><h2 id="k线周期" tabindex="-1">K线周期 <a class="header-anchor" href="#k线周期" aria-label="Permalink to &quot;K线周期&quot;">​</a></h2><p><code>1m</code> <code>3m</code> <code>5m</code> <code>10m</code> <code>15m</code> <code>30m</code> <code>1h</code> <code>2h</code> <code>4h</code> <code>1d</code> <code>1wk</code></p><h2 id="下单价格类型" tabindex="-1">下单价格类型 <a class="header-anchor" href="#下单价格类型" aria-label="Permalink to &quot;下单价格类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>市价</td><td>以当前市场最优价立即成交</td></tr><tr><td>对手价</td><td>以对手方报价委托（买入取卖一价，卖出取买一价）</td></tr><tr><td>排队价</td><td>以己方排队价委托（买入取买一价，卖出取卖一价）</td></tr><tr><td>限价</td><td>自定义价格委托</td></tr></tbody></table><h2 id="模组选项" tabindex="-1">模组选项 <a class="header-anchor" href="#模组选项" aria-label="Permalink to &quot;模组选项&quot;">​</a></h2><h3 id="模组用途" tabindex="-1">模组用途 <a class="header-anchor" href="#模组用途" aria-label="Permalink to &quot;模组用途&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>回测</td><td>在历史回放环境中运行策略</td></tr><tr><td>模拟盘</td><td>在 SIM 模拟账户上试运行策略</td></tr><tr><td>实盘</td><td>在实盘账户上真实交易</td></tr></tbody></table><h3 id="模组类型" tabindex="-1">模组类型 <a class="header-anchor" href="#模组类型" aria-label="Permalink to &quot;模组类型&quot;">​</a></h3><p>投机 / 套利</p><h3 id="平仓逻辑" tabindex="-1">平仓逻辑 <a class="header-anchor" href="#平仓逻辑" aria-label="Permalink to &quot;平仓逻辑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>选项</th><th>全称</th><th>说明</th></tr></thead><tbody><tr><td>FIFO</td><td>先开先平</td><td>按开仓顺序平仓</td></tr><tr><td>FILO</td><td>平今优先</td><td>优先平今日新开仓位</td></tr><tr><td>CPHT</td><td>平昨锁今</td><td>平昨仓同时锁住今仓（仅实盘可选，适用于有平今高手续费的品种）</td></tr></tbody></table><h3 id="模组状态" tabindex="-1">模组状态 <a class="header-anchor" href="#模组状态" aria-label="Permalink to &quot;模组状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>无持仓</td><td>空闲</td></tr><tr><td>多头持仓 / 空头持仓</td><td>单向持仓</td></tr><tr><td>对冲锁仓 / 对冲持仓</td><td>双向持仓</td></tr><tr><td>等待中</td><td>已下单等待订单反馈</td></tr><tr><td>异常</td><td>运行出错（查模组日志）</td></tr></tbody></table><h3 id="网关连接状态" tabindex="-1">网关连接状态 <a class="header-anchor" href="#网关连接状态" aria-label="Permalink to &quot;网关连接状态&quot;">​</a></h3><p>连接中 / 已连接 / 断开中 / 已断开；行情网关另有 行情：活跃 / 不活跃。</p><h2 id="图表工具" tabindex="-1">图表工具 <a class="header-anchor" href="#图表工具" aria-label="Permalink to &quot;图表工具&quot;">​</a></h2><ul><li><strong>图表数</strong>：1 / 2 / 3 / 4 / 5 / 6 / 9 / 12 宫格</li><li><strong>画线工具</strong>：直线、水平线、斐波那契、三浪五浪等</li><li><strong>画线交易</strong>：多头、空头、止盈、止损、交易计划</li><li><strong>图表通用设定</strong>：K线配色（红涨绿跌 / 绿涨红跌）、历史持仓线、主图/副图指标</li></ul><h2 id="环境-profile-部署参考" tabindex="-1">环境 Profile（部署参考） <a class="header-anchor" href="#环境-profile-部署参考" aria-label="Permalink to &quot;环境 Profile（部署参考）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profile</th><th>端口</th><th>SSL</th><th>数据库</th></tr></thead><tbody><tr><td><code>prod</code>（默认）/ <code>demo</code></td><td>443</td><td>启用</td><td>H2 文件模式</td></tr><tr><td><code>dev</code></td><td>80</td><td>禁用</td><td>H2 文件模式</td></tr><tr><td><code>test</code> / <code>unittest</code> / <code>train</code> / <code>devtest</code></td><td>80</td><td>禁用</td><td>H2 内存模式</td></tr></tbody></table><p>通过 <code>-Denv=&lt;profile&gt;</code> 启动参数切换，如 <code>java -Denv=dev -jar northstar-x.y.z.jar</code>。</p>',28)])])}const u=d(o,[["render",l]]);export{x as __pageData,u as default};
